/* The tables of M25 · Tax and compliance. */

/** One row per organisation. */
export const taxProfile = defineTable(
  'tax_profile',
  { module: 'M25', scope: 'org' },
  {
    ...baseColumns,
    legalName: text().notNull(),
    /** printed on receipts and certificates */
    ntn: text(),
    strn: text(),
    taxOffice: text(),
    taxYearStartMonth: integer().notNull().default(7),
    withholdingAgent: boolean().notNull().default(true),
    eobiRegistrationNo: text(),
    socialSecurityNo: text(),
    adviserName: text(),
    adviserPhone: text(),
  },
  (t) => [uniqueIndex('tax_profile_org_uq').on(t.orgId).where(live(t))],
);

/** A rule in force for a span of dates. */
export const taxRules = defineTable(
  'tax_rules',
  { module: 'M25', scope: 'org' },
  {
    ...baseColumns,
    kind: enumText(taxRuleKinds).notNull(),
    /** "Salary tax slabs, tax year 2027" */
    name: text().notNull(),
    /** for provincial rules */
    province: text(),
    effectiveFrom: dateStr().notNull(),
    effectiveTo: dateStr(),
    /** its shape depends on `kind`, see §4 */
    params: jsonb().notNull(),
    /** where the figures came from: the notification or Finance Act section */
    sourceNote: text().notNull(),
    status: enumText(taxRuleStatuses).notNull().default('draft'),
    confirmedBy: uuid().references((): AnyPgColumn => profiles.id),
    confirmedAt: timestamptz(),
  },
);

/** Tax details of someone the school deals with. */
export const taxPartyProfiles = defineTable(
  'tax_party_profiles',
  { module: 'M25', scope: 'org', self: 'userId' },
  {
    ...baseColumns,
    partyType: enumText(taxPartyProfilePartyTypes).notNull(),
    partyId: uuid().notNull(),
    /** the person's own login, so they can read it */
    userId: uuid().references((): AnyPgColumn => profiles.id),
    ntn: text(),
    cnic: text(),
    filerStatus: enumText(taxPartyProfileFilerStatuses).notNull().default('unknown'),
    /** when someone last checked the active taxpayer list */
    statusCheckedOn: dateStr(),
    /** an exemption certificate */
    exemptionFileId: uuid().references((): AnyPgColumn => files.id),
    exemptionValidTo: dateStr(),
  },
  (t) => [
    uniqueIndex('tax_party_profiles_party_type_party_uq').on(t.partyType, t.partyId).where(live(t)),
  ],
);

/** Every amount of tax collected or withheld, whatever its source. */
export const taxDeductions = defineTable(
  'tax_deductions',
  { module: 'M25', scope: 'org', appendOnly: true, staff: 'append' },
  {
    ...appendColumns,
    kind: enumText(taxDeductionKinds).notNull(),
    branchId: uuid()
      .references((): AnyPgColumn => branches.id)
      .notNull(),
    partyType: enumText(taxDeductionPartyTypes).notNull(),
    partyId: uuid().notNull(),
    taxPeriod: dateStr().notNull(),
    baseAmount: paisa().notNull(),
    /** negative for a reversal */
    taxAmount: paisa().notNull(),
    ratePercent: decimal(6, 3),
    /** the rule used */
    ruleId: uuid()
      .references((): AnyPgColumn => taxRules.id)
      .notNull(),
    /** `payslip`, `fee_voucher_line`, `vendor_payment` */
    sourceType: text().notNull(),
    sourceId: uuid().notNull(),
    /** set when it is included in a deposit */
    filingId: uuid().references((): AnyPgColumn => statutoryFilings.id),
  },
  (t) => [
    check('tax_deductions_tax_period_first', sql`extract(day from ${t.taxPeriod}) = 1`),
    uniqueIndex('tax_deductions_source_type_source_kind_uq')
      .on(t.sourceType, t.sourceId, t.kind)
      .where(sql`${t.taxAmount} > 0`),
    index('tax_deductions_kind_tax_period_idx').on(t.orgId, t.kind, t.taxPeriod),
    index('tax_deductions_party_type_party_tax_period_idx').on(
      t.orgId,
      t.partyType,
      t.partyId,
      t.taxPeriod,
    ),
  ],
);

/** A deposit or statement that is due. */
export const statutoryFilings = defineTable(
  'statutory_filings',
  { module: 'M25', scope: 'org' },
  {
    ...baseColumns,
    kind: enumText(statutoryFilingKinds).notNull(),
    branchId: uuid().references((): AnyPgColumn => branches.id),
    periodFrom: dateStr().notNull(),
    periodTo: dateStr().notNull(),
    dueDate: dateStr().notNull(),
    /** computed from deductions or payroll when prepared */
    amount: paisa().notNull().default(0),
    status: enumText(statutoryFilingStatuses).notNull().default('upcoming'),
    /** the CPR or challan number */
    paymentReference: text(),
    paidOn: dateStr(),
    bankAccountId: uuid().references((): AnyPgColumn => bankAccounts.id),
    /** the paid challan or acknowledgement */
    fileId: uuid().references((): AnyPgColumn => files.id),
    /** the schedule Takhti produced */
    workingDocumentId: uuid().references((): AnyPgColumn => generatedDocuments.id, {
      name: 'statutory_filings_working_document_id_generated_docume_4b658104',
    }),
    preparedBy: uuid().references((): AnyPgColumn => profiles.id),
  },
  (t) => [
    nonNegative('statutory_filings', t.amount),
    uniqueIndex('statutory_filings_kind_branch_period_from_uq')
      .on(
        t.orgId,
        t.kind,
        sql`coalesce(${t.branchId}, '00000000-0000-0000-0000-000000000000'::uuid)`,
        t.periodFrom,
      )
      .where(live(t)),
  ],
);

